namespace ghidra.app.plugin.core.function;





using docking;
using docking.action;
using docking.action;
using ghidra.app.context;
using ghidra.app.services;
using ghidra.program.model.data;
using ghidra.program.model.data;
using ghidra.program.util;
using ghidra.util;

public class RecentlyUsedAction : DataAction {
	private static KeyStroke DEFAULT_KEY_STROKE = KeyStroke.getKeyStroke(KeyEvent.VK_Y, 0);
	private static string GROUP_NAME = "Z_RECENT";

	public RecentlyUsedAction(FunctionPlugin plugin) : base("Recently Used", "Recent", new ByteDataType(), plugin)
    {

		setHelpLocation(new HelpLocation(plugin.getName(), "Recently_Used"));
	}

	/* @Override */
	protected KeyStroke getDefaultKeyStroke() {
		return DEFAULT_KEY_STROKE; // we have no default, but our subclasses may
	}

	/* @Override */
	protected void initKeyStroke(KeyStroke keyStroke) {
		if (!DEFAULT_KEY_STROKE.equals(keyStroke)) {
			// user-defined keystroke
			setUnvalidatedKeyBindingData(new KeyBindingData(keyStroke));
		}
		else {
			setKeyBindingData(new KeyBindingData(keyStroke));
		}
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		DataType recentDataType = getRecentDataType();
		if (recentDataType == null) {
			return false;
		}

		this.dataType = recentDataType;
		
		bool enabled = base.isEnabledForContext(context);
		return enabled;
	}

	/* @Override */
	protected bool isAddToPopup(ListingActionContext context) {
		ProgramLocation location = context.getLocation();
		if (location is FunctionSignatureFieldLocation) {
			return true;
		}
		if (location is VariableLocation) {
			return true;
		}
		return false;
	}

	private DataType getRecentDataType() {
		DataTypeManagerService service = plugin.getTool().getService(typeof(DataTypeManagerService));
		if (service == null) {
			return null;
		}
		return service.getRecentlyUsed();
	}

	/* @Override */
	public void setPopupMenu(string name, bool isSignatureAction) {
		DataType dt = getRecentDataType();
		string displayName = "Last Used: " + (dt == null ? "<empty>" : dt.getDisplayName());

		setPopupMenuData(new MenuData(new string[] { FunctionPlugin.SET_DATA_TYPE_PULLRIGHT,
			displayName }, GROUP_NAME));
	}
}
